import{_ as a,o as t,c as i,a5 as s}from"./chunks/framework.UjrY2eRK.js";const c=JSON.parse('{"title":"Publish minimal attested Bun images from stable releases","description":"","frontmatter":{},"headers":[],"relativePath":"architecture/adr/0018-publish-minimal-attested-bun-images-from-stable-releases.md","filePath":"architecture/adr/0018-publish-minimal-attested-bun-images-from-stable-releases.md","lastUpdated":1788123021000}'),n={name:"architecture/adr/0018-publish-minimal-attested-bun-images-from-stable-releases.md"};function r(o,e,l,d,m,u){return t(),i("div",null,[...e[0]||(e[0]=[s('<h1 id="publish-minimal-attested-bun-images-from-stable-releases" tabindex="-1">Publish minimal attested Bun images from stable releases <a class="header-anchor" href="#publish-minimal-attested-bun-images-from-stable-releases" aria-label="Permalink to &quot;Publish minimal attested Bun images from stable releases&quot;">​</a></h1><p>Each stable release will publish a Bun-targeted application bundle in a hardened official Bun slim image pinned by version and multi-platform digest. GitHub Container Registry will receive one AMD64 and ARM64 manifest under immutable <code>vX.Y.Z</code> and moving <code>latest</code> tags, with an SBOM, provenance attestation, and image digest attached to the GitHub Release; ordinary merges and unmerged release pull requests will not publish images.</p><p>The runtime image contains the application bundle and canonical SQL migrations but excludes pnpm, Wrangler, development dependencies, tests, and source tooling. pnpm and <code>pnpm-lock.yaml</code> remain the sole dependency-resolution authority, while Dependabot proposes Bun base-image updates and CI smoke-tests the AMD64 image before merge and both architectures before publication.</p><p>Production support covers the supplied Linux image on AMD64 and ARM64. It runs as the fixed non-root Bun user with a read-only root filesystem, a local named volume for <code>/data</code>, no Linux capabilities or privilege escalation, and no automatic updater; production deployments pin an immutable version or digest and upgrade explicitly after a verified backup. Image publication uses a narrowly permitted ephemeral GitHub token and never grants package authority to the Release Please token or pull-request workflows.</p><p>CI reports unpacked and compressed image size and rejects an AMD64 image above 150 MiB compressed. A release whose downstream image publication fails retains its immutable tag and failed workflow for safe rerun; the release notes receive the image digest only after both architectures, SBOM generation, and provenance attestation succeed. The runtime image supplies its health probe through Bun rather than adding a diagnostic package solely for Docker.</p>',5)])])}const h=a(n,[["render",r]]);export{c as __pageData,h as default};
